import React, { useState, useCallback, useRef } from 'react';
import { useDropzone } from 'react-dropzone';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { UploadCloud, Download, BarChart2, Bluetooth, PlayCircle, ZapOff } from 'lucide-react';

// --- FTMS Constants ---
const FTMS_SERVICE_UUID = '00001826-0000-1000-8000-00805f9b34fb';
const TREADMILL_DATA_CHAR_UUID = '00002acd-0000-1000-8000-00805f9b34fb';
const FITNESS_MACHINE_CONTROL_POINT_CHAR_UUID = '00002ad9-0000-1000-8000-00805f9b34fb';

// --- Helper Functions ---

// Haversine formula to calculate distance between two lat/lon points
const getDistance = (lat1, lon1, lat2, lon2) => {
    const R = 6371; // Radius of the earth in km
    const dLat = deg2rad(lat2 - lat1);
    const dLon = deg2rad(lon2 - lon1);
    const a =
        Math.sin(dLat / 2) * Math.sin(dLat / 2) +
        Math.cos(deg2rad(lat1)) * Math.cos(deg2rad(lat2)) *
        Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c * 1000; // Distance in meters
};

const deg2rad = (deg) => deg * (Math.PI / 180);

// Simple moving average to smooth elevation data
const smoothElevation = (points, windowSize = 5) => {
    if (points.length < windowSize) return points;
    return points.map((point, index, arr) => {
        if (index < Math.floor(windowSize / 2) || index >= arr.length - Math.floor(windowSize / 2)) {
            return { ...point };
        }
        const window = arr.slice(index - Math.floor(windowSize / 2), index + Math.ceil(windowSize / 2));
        const avgEle = window.reduce((sum, p) => sum + p.ele, 0) / window.length;
        return { ...point, ele: parseFloat(avgEle.toFixed(2)) };
    });
};

// Main App Component
export default function App() {
    const [fileName, setFileName] = useState('');
    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    
    // Route and workout state
    const [routeData, setRouteData] = useState(null);
    const [workout, setWorkout] = useState([]);
    
    // Bluetooth and run state
    const [device, setDevice] = useState(null);
    const [isConnected, setIsConnected] = useState(false);
    const [isRunning, setIsRunning] = useState(false);
    const [runData, setRunData] = useState({ speed: 0, distance: 0, incline: 0 });
    const [statusMessage, setStatusMessage] = useState('Please select a GPX file.');

    // Refs to hold characteristics and workout progress
    const controlPointChar = useRef(null);
    const workoutIndex = useRef(0);

    const onDrop = useCallback((acceptedFiles) => {
        setIsLoading(true);
        setRouteData(null);
        setError('');
        setFileName('');
        setWorkout([]);

        if (acceptedFiles.length > 0) {
            const file = acceptedFiles[0];
            setFileName(file.name);
            const reader = new FileReader();
            reader.onload = (event) => {
                try {
                    parseGpx(event.target.result);
                } catch (e) {
                    setError("Failed to parse the file. It might be corrupted or not a valid GPX.");
                    setIsLoading(false);
                }
            };
            reader.onerror = () => {
                setError("Failed to read the file.");
                setIsLoading(false);
            };
            reader.readAsText(file);
        }
    }, []);

    const parseGpx = (gpxString) => {
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(gpxString, "text/xml");
        const trackPoints = xmlDoc.getElementsByTagName('trkpt');

        if (trackPoints.length === 0) {
            setError("No track points found in the GPX file.");
            setIsLoading(false);
            return;
        }

        let totalDistance = 0;
        const points = Array.from(trackPoints).map((point, index) => {
            const lat = parseFloat(point.getAttribute('lat'));
            const lon = parseFloat(point.getAttribute('lon'));
            const ele = parseFloat(point.getElementsByTagName('ele')[0]?.textContent || 0);

            if (index > 0) {
                const prevPoint = trackPoints[index - 1];
                const prevLat = parseFloat(prevPoint.getAttribute('lat'));
                const prevLon = parseFloat(prevPoint.getAttribute('lon'));
                totalDistance += getDistance(prevLat, prevLon, lat, lon);
            }
            return { lat, lon, ele, dist: totalDistance / 1000 };
        });

        const smoothedPoints = smoothElevation(points);
        setRouteData(smoothedPoints);
        generateWorkoutPlan(smoothedPoints);
        setError('');
        setIsLoading(false);
        setStatusMessage('GPX file loaded. Ready to connect to treadmill.');
    };

    const generateWorkoutPlan = (points) => {
        const plan = [];
        if (points.length < 2) return;

        for (let i = 1; i < points.length; i++) {
            const startPoint = points[i-1];
            const endPoint = points[i];
            
            const distanceMeters = (endPoint.dist - startPoint.dist) * 1000;
            if (distanceMeters < 5) continue; // Ignore very short segments

            const elevationChange = endPoint.ele - startPoint.ele;
            const gradient = (elevationChange / distanceMeters) * 100;
            const roundedGradient = Math.round(gradient * 2) / 2;

            plan.push({
                distanceKm: endPoint.dist,
                incline: roundedGradient,
            });
        }
        setWorkout(plan);
    };

    const handleConnect = async () => {
        if (!navigator.bluetooth) {
            setError("Web Bluetooth is not available on this browser. Try Chrome on Desktop or Android.");
            return;
        }
        try {
            setStatusMessage("Scanning for Bluetooth devices...");
            const ftmsDevice = await navigator.bluetooth.requestDevice({
                filters: [{ services: [FTMS_SERVICE_UUID] }],
                optionalServices: [FTMS_SERVICE_UUID]
            });
            setDevice(ftmsDevice);
            setStatusMessage(`Connecting to ${ftmsDevice.name}...`);

            ftmsDevice.addEventListener('gattserverdisconnected', onDisconnected);
            const server = await ftmsDevice.gatt.connect();
            const service = await server.getPrimaryService(FTMS_SERVICE_UUID);
            
            // Get Control Point Characteristic
            controlPointChar.current = await service.getCharacteristic(FITNESS_MACHINE_CONTROL_POINT_CHAR_UUID);
            
            // Get Treadmill Data Characteristic and start notifications
            const treadmillDataChar = await service.getCharacteristic(TREADMILL_DATA_CHAR_UUID);
            await treadmillDataChar.startNotifications();
            treadmillDataChar.addEventListener('characteristicvaluechanged', handleTreadmillData);

            setIsConnected(true);
            setStatusMessage(`Connected to ${ftmsDevice.name}. Ready to run!`);

        } catch (e) {
            setError(`Connection failed: ${e.message}`);
            setStatusMessage('Connection failed. Please try again.');
        }
    };
    
    const onDisconnected = () => {
        setIsConnected(false);
        setIsRunning(false);
        setDevice(null);
        controlPointChar.current = null;
        setStatusMessage("Treadmill disconnected.");
    };

    const handleDisconnect = () => {
        if (device && device.gatt.connected) {
            device.gatt.disconnect();
        }
    };

    const handleStartRun = async () => {
        if (!controlPointChar.current) return;
        try {
            // Request control
            await controlPointChar.current.writeValue(new Uint8Array([0x00]));
            // Start the machine
            await controlPointChar.current.writeValue(new Uint8Array([0x07]));
            setIsRunning(true);
            workoutIndex.current = 0;
            setStatusMessage("Workout started!");
        } catch (e) {
            setError(`Could not start run: ${e.message}`);
        }
    };

    const handleTreadmillData = (event) => {
        const value = event.target.value;
        // FTMS Treadmill Data packet parsing
        // This is a simplified parser. A full implementation is more complex.
        const flags = value.getUint16(0, true);
        let index = 2;

        const speedKmh = value.getUint16(index, true) / 100;
        index += 2;
        
        const totalDistanceMeters = value.getUint16(index, true) * 10;
        index += 2;

        const incline = value.getInt16(index, true) / 10;
        
        setRunData({ speed: speedKmh, distance: totalDistanceMeters / 1000, incline });

        // Workout logic
        if (isRunning && workout.length > 0) {
            const currentDistanceKm = totalDistanceMeters / 1000;
            const nextStep = workout[workoutIndex.current];

            if (nextStep && currentDistanceKm >= nextStep.distanceKm) {
                setIncline(nextStep.incline);
                workoutIndex.current += 1;
                if (workoutIndex.current >= workout.length) {
                    setIsRunning(false); // End of workout
                    setStatusMessage("Workout complete!");
                }
            }
        }
    };

    const setIncline = async (incline) => {
        if (!controlPointChar.current) return;
        try {
            // FTMS command to set incline: Op Code 0x05, followed by signed int16 incline value * 10
            const buffer = new ArrayBuffer(3);
            const view = new DataView(buffer);
            view.setUint8(0, 0x05); // Set Target Inclination Op Code
            view.setInt16(1, incline * 10, true); // Incline value
            
            await controlPointChar.current.writeValue(view);
            setStatusMessage(`Incline set to ${incline}%`);
        } catch (e) {
            console.error(`Failed to set incline: ${e.message}`);
        }
    };

    const { getRootProps, getInputProps, isDragActive } = useDropzone({
        onDrop,
        accept: { 'application/gpx+xml': ['.gpx'] },
        multiple: false
    });

    return (
        <div className="bg-gray-50 min-h-screen font-sans text-gray-800">
            <div className="container mx-auto p-4 sm:p-6 lg:p-8">
                <header className="text-center mb-8">
                    <h1 className="text-4xl sm:text-5xl font-bold text-blue-600">Parkrun to Treadmill</h1>
                    <p className="text-lg text-gray-600 mt-2">Practice any parkrun route on your smart treadmill.</p>
                </header>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 max-w-6xl mx-auto">
                    {/* Left Column: Setup */}
                    <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-200 flex flex-col gap-6">
                        <div>
                           <h2 className="text-xl font-bold mb-3">1. Load Route</h2>
                            <div {...getRootProps()} className={`relative border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-all duration-300 ${isDragActive ? 'border-blue-500 bg-blue-50' : 'border-gray-300 hover:border-blue-400 hover:bg-gray-50'}`}>
                                <input {...getInputProps()} />
                                <div className="flex flex-col items-center justify-center text-gray-500">
                                    <UploadCloud className="w-10 h-10 mb-3 text-gray-400" />
                                    {isLoading ? <p>Processing...</p> : <p className="font-semibold">Drop .gpx file or click</p>}
                                </div>
                            </div>
                            {fileName && !isLoading && <p className="mt-3 text-center text-sm">Loaded: <strong>{fileName}</strong></p>}
                        </div>
                        
                        <div>
                            <h2 className="text-xl font-bold mb-3">2. Connect Treadmill</h2>
                            <div className="flex flex-col items-center">
                                {!isConnected ? (
                                    <button onClick={handleConnect} disabled={!routeData} className="w-full inline-flex items-center justify-center gap-2 px-6 py-3 bg-blue-500 text-white font-bold rounded-lg shadow-md hover:bg-blue-600 transition disabled:bg-gray-300 disabled:cursor-not-allowed">
                                        <Bluetooth className="w-5 h-5" /> Connect to Treadmill
                                    </button>
                                ) : (
                                    <button onClick={handleDisconnect} className="w-full inline-flex items-center justify-center gap-2 px-6 py-3 bg-red-500 text-white font-bold rounded-lg shadow-md hover:bg-red-600 transition">
                                        <ZapOff className="w-5 h-5" /> Disconnect
                                    </button>
                                )}
                            </div>
                        </div>

                        <div>
                            <h2 className="text-xl font-bold mb-3">3. Start Workout</h2>
                             <div className="flex flex-col items-center">
                                <button onClick={handleStartRun} disabled={!isConnected || isRunning} className="w-full inline-flex items-center justify-center gap-2 px-6 py-3 bg-green-500 text-white font-bold rounded-lg shadow-md hover:bg-green-600 transition disabled:bg-gray-300 disabled:cursor-not-allowed">
                                    <PlayCircle className="w-5 h-5" /> Start Run
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Right Column: Status and Chart */}
                    <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-200 flex flex-col">
                        <h2 className="text-xl font-bold mb-4 text-center">Live Status</h2>
                        <div className="bg-gray-100 p-4 rounded-lg text-center mb-4">
                            <p className="font-semibold text-gray-700">{statusMessage}</p>
                        </div>
                        
                        <div className="grid grid-cols-3 gap-4 text-center mb-6">
                            <div>
                                <p className="text-sm text-gray-500">Speed</p>
                                <p className="text-2xl font-bold">{runData.speed.toFixed(1)} <span className="text-base font-normal">km/h</span></p>
                            </div>
                             <div>
                                <p className="text-sm text-gray-500">Distance</p>
                                <p className="text-2xl font-bold">{runData.distance.toFixed(2)} <span className="text-base font-normal">km</span></p>
                            </div>
                             <div>
                                <p className="text-sm text-gray-500">Incline</p>
                                <p className="text-2xl font-bold">{runData.incline.toFixed(1)}<span className="text-base font-normal">%</span></p>
                            </div>
                        </div>
                        
                        {error && <div className="p-3 bg-red-100 border border-red-400 text-red-700 rounded-lg text-center mb-4"><p>{error}</p></div>}

                        <div className="flex-grow min-h-[300px]">
                             {routeData ? (
                                <ResponsiveContainer width="100%" height="100%">
                                    <LineChart data={routeData} margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
                                        <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
                                        <XAxis dataKey="dist" type="number" domain={['dataMin', 'dataMax']} tickFormatter={(km) => `${km.toFixed(1)}`} unit=" km"/>
                                        <YAxis domain={['dataMin - 5', 'dataMax + 5']} unit=" m"/>
                                        <Tooltip formatter={(value) => [`${value.toFixed(1)} m`, 'Elevation']} labelFormatter={(label) => `Distance: ${label.toFixed(2)} km`}/>
                                        <Legend />
                                        <Line type="monotone" dataKey="ele" name="Elevation" stroke="#3b82f6" strokeWidth={2} dot={false} />
                                    </LineChart>
                                </ResponsiveContainer>
                             ) : (
                                <div className="h-full flex items-center justify-center text-gray-400">
                                    <p>Upload a GPX file to see the elevation profile.</p>
                                </div>
                             )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
